import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

namespace lnorm_detail {

constexpr int kThreads = 1024;

__device__ __forceinline__ void accum4(float4 v, float shift, double& s, double& q) {
  float d0 = v.x - shift;
  float d1 = v.y - shift;
  float d2 = v.z - shift;
  float d3 = v.w - shift;
  s += (double)((d0 + d1) + (d2 + d3));
  q += (double)fmaf(d0, d0, fmaf(d1, d1, fmaf(d2, d2, d3 * d3)));
}

__device__ __forceinline__ float4 norm4(float4 xv, float4 wv, float4 bv,
                                        float shift, float mean_d, float rstd) {
  float4 o;
  o.x = fmaf(((xv.x - shift) - mean_d) * rstd, wv.x, bv.x);
  o.y = fmaf(((xv.y - shift) - mean_d) * rstd, wv.y, bv.y);
  o.z = fmaf(((xv.z - shift) - mean_d) * rstd, wv.z, bv.z);
  o.w = fmaf(((xv.w - shift) - mean_d) * rstd, wv.w, bv.w);
  return o;
}

// One block per normalization row. Row length N may be very large, so the
// whole block cooperates on a single row: pass 1 computes shifted sum and
// sum-of-squares (numerically stable for large-mean inputs), pass 2 writes
// the normalized output. Vectorized float4 accesses via CuTe tensors.
__global__ __launch_bounds__(kThreads)
void layernorm_fwd_kernel(const float* __restrict__ X,
                          const float* __restrict__ W,
                          const float* __restrict__ B,
                          float* __restrict__ Y,
                          int64_t N,
                          float eps)
{
  const int64_t row = blockIdx.x;
  const int tid = threadIdx.x;

  const float* xrow = X + row * N;
  float*       yrow = Y + row * N;

  // Scalar views
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(N), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(yrow), make_shape(N), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(W),    make_shape(N), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(B),    make_shape(N), make_stride(Int<1>{}));

  // Vectorized views (only used when N % 4 == 0 so every row is 16B aligned)
  const bool    vec_ok = ((N & 3) == 0);
  const int64_t NV     = vec_ok ? (N >> 2) : 0;

  Tensor gXv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gYv = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(yrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gWv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(W)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gBv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(B)),
                           make_shape(NV), make_stride(Int<1>{}));

  // Shift by the first element for numerical stability (large means).
  const float shift = gX(0);

  // ---- Pass 1: shifted sum / sum-of-squares ----
  double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
  double q0 = 0.0, q1 = 0.0, q2 = 0.0, q3 = 0.0;

  int64_t i = tid;
  for (; i + 3 * kThreads < NV; i += 4 * kThreads) {
    float4 v0 = gXv(i);
    float4 v1 = gXv(i + kThreads);
    float4 v2 = gXv(i + 2 * kThreads);
    float4 v3 = gXv(i + 3 * kThreads);
    accum4(v0, shift, s0, q0);
    accum4(v1, shift, s1, q1);
    accum4(v2, shift, s2, q2);
    accum4(v3, shift, s3, q3);
  }
  for (; i < NV; i += kThreads) {
    accum4(gXv(i), shift, s0, q0);
  }
  // Scalar tail (covers N % 4 != 0 case, including NV == 0)
  for (int64_t j = (NV << 2) + tid; j < N; j += kThreads) {
    float d = gX(j) - shift;
    s0 += (double)d;
    q0 += (double)d * (double)d;
  }

  double lsum = (s0 + s1) + (s2 + s3);
  double lsq  = (q0 + q1) + (q2 + q3);

  // ---- Block reduction (warp shuffle + shared memory) ----
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    lsum += __shfl_down_sync(0xffffffffu, lsum, off);
    lsq  += __shfl_down_sync(0xffffffffu, lsq,  off);
  }

  __shared__ double s_wsum[kThreads / 32];
  __shared__ double s_wsq [kThreads / 32];
  __shared__ float  s_mean_d;
  __shared__ float  s_rstd;

  const int lane = tid & 31;
  const int warp = tid >> 5;

  if (lane == 0) {
    s_wsum[warp] = lsum;
    s_wsq [warp] = lsq;
  }
  __syncthreads();

  if (warp == 0) {
    double a = s_wsum[lane];
    double q = s_wsq [lane];
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      a += __shfl_down_sync(0xffffffffu, a, off);
      q += __shfl_down_sync(0xffffffffu, q, off);
    }
    if (lane == 0) {
      double invN = 1.0 / (double)N;
      double md   = a * invN;                    // mean of (x - shift)
      double var  = q * invN - md * md;          // Var(x - shift) == Var(x)
      if (var < 0.0) var = 0.0;
      s_mean_d = (float)md;
      s_rstd   = (float)(1.0 / sqrt(var + (double)eps));
    }
  }
  __syncthreads();

  const float mean_d = s_mean_d;
  const float rstd   = s_rstd;

  // ---- Pass 2: normalize and write ----
  i = tid;
  for (; i + kThreads < NV; i += 2 * kThreads) {
    float4 x0 = gXv(i);
    float4 x1 = gXv(i + kThreads);
    float4 w0 = gWv(i);
    float4 w1 = gWv(i + kThreads);
    float4 b0 = gBv(i);
    float4 b1 = gBv(i + kThreads);
    gYv(i)            = norm4(x0, w0, b0, shift, mean_d, rstd);
    gYv(i + kThreads) = norm4(x1, w1, b1, shift, mean_d, rstd);
  }
  for (; i < NV; i += kThreads) {
    gYv(i) = norm4(gXv(i), gWv(i), gBv(i), shift, mean_d, rstd);
  }
  for (int64_t j = (NV << 2) + tid; j < N; j += kThreads) {
    float d = gX(j) - shift;
    gY(j) = fmaf((d - mean_d) * rstd, gW(j), gB(j));
  }
}

} // namespace lnorm_detail

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda(),
              "x, weight and bias must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat &&
              weight.scalar_type() == at::kFloat &&
              bias.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(weight.numel() == bias.numel(), "weight and bias must have same numel");

  const int64_t N = weight.numel();
  TORCH_CHECK(N > 0, "normalized dimension must be > 0");

  const int wd = weight.dim();
  TORCH_CHECK(x.dim() >= wd, "x must have at least as many dims as weight");
  for (int k = 0; k < wd; ++k) {
    TORCH_CHECK(x.size(x.dim() - wd + k) == weight.size(k),
                "Trailing dims of x must match normalized_shape");
  }
  TORCH_CHECK(x.numel() % N == 0, "x.numel() must be divisible by weight.numel()");

  const int64_t M = x.numel() / N;
  TORCH_CHECK(M > 0 && M <= 0x7fffffff, "Invalid number of rows");

  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  auto bc = bias.contiguous();

  auto y = torch::empty_like(xc);

  dim3 grid((unsigned)M);
  dim3 block(lnorm_detail::kThreads);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  lnorm_detail::layernorm_fwd_kernel<<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bc.data_ptr<float>(),
      y.data_ptr<float>(),
      N,
      (float)eps);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm_fwd_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single custom CUDA/CuTe kernel.

    One thread block cooperatively normalizes one row of length
    N = prod(normalized_shape): pass 1 computes shifted sum and
    sum-of-squares with a block reduction (stable for large-mean inputs),
    pass 2 writes the affine-transformed normalized output. All global
    memory accesses go through CuTe tensors with float4 vectorization.
    """
    def __init__(self, normalized_shape) -> None:
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        # Same initialization as nn.LayerNorm (weight=1, bias=0).
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.is_cuda and x.dtype == torch.float32:
            return self._ext.layernorm_forward(
                x.contiguous(),
                self.weight.contiguous(),
                self.bias.contiguous(),
                float(self.eps),
            )
        return F.layer_norm(x, self.normalized_shape, self.weight, self.bias, self.eps)

